<?php
require_once 'db_connect.php';session_start();if(empty($_SESSION['user_id'])||($_SESSION['user_role']??'')!=='customer'){header('Location: login.php');exit;}
$email=$_SESSION['user_email']??'';if($email===''){$st=$conn->prepare("SELECT email FROM users WHERE id=?");$st->bind_param('i',$_SESSION['user_id']);$st->execute();$email=$st->get_result()->fetch_assoc()['email']??'';$st->close();}
$st=$conn->prepare("SELECT id,vehicle,service_name,service_date,status FROM appointments WHERE email=? ORDER BY id DESC");$st->bind_param('s',$email);$st->execute();$rows=$st->get_result();function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>My Appointments</title><link rel="stylesheet" href="style.css"></head><body><header><h1>My Appointments</h1><p>Welcome, <?=e($_SESSION['user_name']??'Customer')?></p></header><nav class="navbar"><a href="index.php">Home</a><a href="logout.php">Logout</a></nav><main><section class="panel"><h2>Your bookings</h2><div class="table-wrap"><table><thead><tr><th>ID</th><th>Vehicle</th><th>Service</th><th>Date</th><th>Status</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['id'])?></td><td><?=e($r['vehicle'])?></td><td><?=e($r['service_name'])?></td><td><?=e($r['service_date'])?></td><td><?=e($r['status'])?></td></tr><?php endwhile;else:?><tr><td colspan="5">No appointments found for your account email. Book using the same email address.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
